import org.eclipse.rdf4j.sail.lmdb.LmdbQueryMemoryManager;
import org.junit.jupiter.api.Test;

class NativeProvenanceTableBudgetTest {
	@Test
	void firstDescriptorRequiresItsIndependentContainerAndCaptureWorkspace() {
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(2048L, 2048L);
		try (var ledger = memory.openQuery();
				var replay = new NativeResultReplay(new NativeResultRow.Schema(), null,
						new NativeCancellationToken(), ledger, 65536L)) {
			var tracked = BindingSetOrigin.with(new MapBindingSet(),
					BindingSetOrigin.of(EmptyBindingSet.getInstance()));
			QueryEvaluationException failure = assertThrows(QueryEvaluationException.class,
					() -> replay.append(NativeResultRow.fromBindingSet(tracked)),
					"first publication must fund three backing tables, capture workspace and the exact tracked descriptor");
			assertTrue(failure.getMessage().contains("Result provenance"));
			assertEquals(0L, ledger.usedBytes(),
					"failed admission releases owner and all preflight/table reservations");
			assertThrows(IllegalStateException.class, replay::finish, "a refused descriptor cannot be published later");
		}
		assertEquals(0L, memory.usedBytes());
	}

	@Test
	void sameEmptyPayloadWithoutAuthorityDoesNotAllocateADictionary() {
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(2048L, 2048L);
		try (var ledger = memory.openQuery();
				var replay = new NativeResultReplay(new NativeResultRow.Schema(), null,
						new NativeCancellationToken(), ledger, 65536L)) {
			replay.append(NativeResultRow.fromBindingSet(EmptyBindingSet.getInstance()));
			replay.finish();
			try (var reader = replay.cursor()) {
				assertNotNull(reader.next());
				assertNull(reader.next());
			}
		}
		assertEquals(0L, memory.usedBytes());
	}

	@Test
	void adequatelyFundedFirstDescriptorPreservesTrackedUnknownAndReleasesItsTables() {
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(8192L, 8192L);
		try (var ledger = memory.openQuery();
				var replay = new NativeResultReplay(new NativeResultRow.Schema(), null,
						new NativeCancellationToken(), ledger, 65536L)) {
			var tracked = BindingSetOrigin.with(new MapBindingSet(),
					BindingSetOrigin.of(EmptyBindingSet.getInstance()));
			replay.append(NativeResultRow.fromBindingSet(tracked));
			replay.finish();
			try (var reader = replay.cursor()) {
				NativeResultRow row = reader.next();
				assertNotNull(row);
				assertNull(reader.next());
				QueryBindingSet later = new QueryBindingSet(row.toBindingSet());
				later.setBinding("external", SimpleValueFactory.getInstance().createIRI("urn:table-budget:value"));
				assertFalse(BindingSetOrigin.of(BindingSetOrigin.requestInput(later)).isRequest("external"));
			}
		}
		assertEquals(0L, memory.usedBytes());
	}
}
